class Solution {
public:
    string decodeAtIndex(string s, int k) {
        long long size = 0;
        for (char c : s) {
            if (isdigit(c)) size *= (c - '0');
            else size++;
        }
        for (int i = (int)s.length() - 1; i >= 0; i--) {
            char c = s[i];
            k %= size;
            if (k == 0 && isalpha(c)) return string(1, c);
            if (isdigit(c)) size /= (c - '0');
            else size--;
        }
        return "";
    }
};

class Solution {
    public String decodeAtIndex(String s, int k) {
        long size = 0;
        for (char c : s.toCharArray()) {
            if (Character.isDigit(c)) size *= (c - '0');
            else size++;
        }
        for (int i = s.length() - 1; i >= 0; i--) {
            char c = s.charAt(i);
            k %= size;
            if (k == 0 && Character.isLetter(c)) return String.valueOf(c);
            if (Character.isDigit(c)) size /= (c - '0');
            else size--;
        }
        return "";
    }
}

var decodeAtIndex = function(s, k) {
    let size = 0n;
    for (const c of s) {
        if (/\d/.test(c)) size *= BigInt(c);
        else size += 1n;
    }
    let bk = BigInt(k);
    for (let i = s.length - 1; i >= 0; i--) {
        const c = s[i];
        bk %= size;
        if (bk === 0n && /[a-z]/.test(c)) return c;
        if (/\d/.test(c)) size /= BigInt(c);
        else size -= 1n;
    }
    return "";
};
